SELECT count(1) FROM ( SELECT * FROM ( SELECT ort.* FROM yh_disease_assess_total_report2 ort, yh_user_reginfo reg WHERE ort.user_code = reg.user_code AND (${illness}) AND ( reg.Org_Code IN ( SELECT Org_Code FROM yh_org_tree
province = #{orgCode} OR city = #{orgCode} OR county = #{orgCode}
) ) ORDER BY qtime DESC ) w GROUP BY w.user_code ) AS a
